var DATA = {"dataset": "Service manuals (12 GB)", "mode": "full-mirror", "stale": "24h", "conflict": "Server wins (manuals are read-only)", "ops": "read:0|read:600|read:1500"};
console.log("Dataset: " + DATA.dataset + " | Mode: " + DATA.mode + " | Staleness bound: " + DATA.stale);
var ops = DATA.ops.split("|").map(function (s) { return s.trim(); });
ops.forEach(function (op) {
  var parts = op.split(":").map(function (s) { return s.trim(); });
  var kind = parts[0], age = parseInt(parts[1] || "0", 10);
  var bound = parseInt(DATA.stale, 10) || 0, ok;
  if (DATA.mode === "unavailable") ok = false;
  else if (kind === "write" && /read-only|degraded/.test(DATA.mode)) ok = false;
  else ok = age <= bound || bound === 0;
  console.log("  " + op + " => " + (ok ? "SERVED (" + DATA.mode + ")" : "BLOCKED") + (ok && age > 0 ? " [staleness " + age + "m]" : ""));
});
console.log("Conflict rule: " + DATA.conflict);
console.log("RESULT: offline availability decided for " + ops.length + " operations.");

